---
import { favorites } from '../favorites'

interface Item {
  slug: string
  title: string
  author: string
  year: number
  tags: string[]
}

const { books, tags } = props<{ books: Item[], tags: string[] }>()
const selected = signal<string | undefined>(undefined)
