cat > src/components/contact-form.kay <<'EOF'
---
import { send } from '../routes/contact.kay'
import { validateContact } from '../validate'
import type { ContactErrors } from '../validate'

const clientErrors = signal<ContactErrors | undefined>(undefined)
const errors = (): ContactErrors => clientErrors() ?? send.failed()?.data?.errors ?? {}
const sent = () => send.succeeded()?.data

async function submit(event: SubmitEvent) {
  event.preventDefault()

  const form = event.currentTarget as HTMLFormElement
  const data = new FormData(form)
  const found = validateContact({
    name: String(data.get('name') ?? ''),
    email: String(data.get('email') ?? ''),
    message: String(data.get('message') ?? ''),
  })

  if (Object.keys(found).length > 0) {
    clientErrors.set(found)
    return
  }

  clientErrors.set(undefined)

  try {
    await send(data, { refresh: false })
  }
  catch {
    // The server's own errors show through `send.failed()`.
  }
}
---
form(action={send} method="post" novalidate onSubmit={submit})
  if sent() as message
    p(role="status") {message}
  .py-2
    label(for="name") Name
    input#name(type="text" name="name")
    if errors().name as message
      span.error {message}
  .py-2
    label(for="email") Email
    input#email(type="email" name="email")
    if errors().email as message
      span.error {message}
  .py-2
    label(for="message") Message
    textarea#message(name="message")
    if errors().message as message
      span.error {message}
  button(type="submit") Send
EOF
cat > src/routes/contact.kay <<'EOF'
--- server
import { t } from 'kay'
import ContactForm from '../components/contact-form.kay'
import { validateContact } from '../validate'

export const send = action(t.Object({ name: t.String(), email: t.String(), message: t.String() }), (input, ctx) => {
  const errors = validateContact(input)

  if (Object.keys(errors).length > 0)
    return ctx.fail(422, { errors })

  return `Thanks, ${input.name.trim()}! Your message has been sent.`
})
---
head
  title Contact | Bookshelf
h1.text-3xl.font-bold Contact
ContactForm
EOF
